import { Message, ToolCallMessage } from '@/sync/typesMessage';
import type { TaskItem } from './TaskListView';

// ---------------------------------------------------------------------------
// Pseudo-message inserted at the first TaskCreate position to render the
// single timeline card that replaces the whole task cluster.
// ---------------------------------------------------------------------------

export interface TaskClusterMessage {
    id: string;
    kind: 'task-cluster';
    tasks: TaskItem[];
    collapsedCount: number;
    createdAt: number;
}

export type ClusteredMessage = Message | TaskClusterMessage;

// ---------------------------------------------------------------------------
// Optional map from global task IDs to their index in the taskItems array.
// Populated from TaskCreate result parsing ("Task #N created successfully")
// in the reducer. Passing this avoids position‑based fallback misalignment.
// ---------------------------------------------------------------------------

export interface ClusterOptions {
    taskIdMap?: ReadonlyMap<string, number>;
}

// ---------------------------------------------------------------------------
// Groups TaskCreate/TaskUpdate tool-call messages into a single timeline
// card (TaskClusterMessage). Non‑task tool calls are hidden while any task
// is still active (activeCount > 0). Tool-call messages immediately before
// the first TaskCreate in the same agent turn are also absorbed.
// ---------------------------------------------------------------------------

export function computeMessageClusters(
    messages: readonly Message[],
    options?: ClusterOptions,
): ClusteredMessage[] {
    // ---- Pass 1: collect task state + mark messages to hide -----------------
    const taskItems: TaskItem[] = [];
    let activeCount = 0;
    let currentTaskIdx = -1;
    const completedOnce = new Map<string, boolean>();
    const tidToIdx = new Map<string, number>();
    const hideSet = new Set<number>();
    let firstTaskIdx = -1;
    let firstTaskCreatedAt = 0;
    let firstTaskTime = 0;

    // Buffered TaskUpdates that arrived before firstTaskIdx — replayed later
    const pendingUpdates: { tid: string; status: string }[] = [];

    // Seed tidToIdx from the external taskIdMap (TaskCreate result parsing)
    const extMap = options?.taskIdMap;
    if (extMap) {
        for (const [tid, idx] of extMap) {
            tidToIdx.set(tid, idx);
        }
    }

    const resolveTaskIndex = (tid: string): number => {
        // Direct match by stored id (e.g. description from TaskCreate input)
        let mi = taskItems.findIndex((t) => t.id === tid);
        if (mi >= 0) return mi;
        // External mapping from TaskCreate result parsing
        if (tidToIdx.has(tid)) return tidToIdx.get(tid)!;
        // Numeric-position fallback (taskId is 1-indexed sequential)
        const pi = parseInt(tid, 10) - 1;
        if (pi >= 0 && pi < taskItems.length) {
            tidToIdx.set(tid, pi);
            return pi;
        }
        return -1;
    };

    const applyTaskUpdate = (tid: string, status: string) => {
        const mi = resolveTaskIndex(tid);
        if (mi < 0) return;
        const order: Record<string, number> = { pending: 0, in_progress: 1, completed: 2 };
        const ns = status || taskItems[mi].status;
        if ((order[ns] ?? -1) > (order[taskItems[mi].status] ?? -1)) {
            taskItems[mi] = { ...taskItems[mi], status: ns as TaskItem['status'] };
        }
        if (ns === 'completed' && !completedOnce.get(taskItems[mi].id)) {
            completedOnce.set(taskItems[mi].id, true);
            activeCount = Math.max(0, activeCount - 1);
        }
        currentTaskIdx = mi;
    };

    for (let i = 0; i < messages.length; i++) {
        const m = messages[i];

        if (m.kind === 'tool-call' && m.tool?.name === 'TaskCreate') {
            const input = m.tool?.input || {};
            const content = input.subject || input.description || input.activeForm || '';
            const descKey = input.description || '';
            taskItems.push({
                id: descKey || String(taskItems.length + 1),
                content,
                status: 'pending',
                collapsedCount: 0,
            });
            activeCount++;
            currentTaskIdx = taskItems.length - 1;
            if (firstTaskIdx < 0) {
                firstTaskIdx = i;
                firstTaskCreatedAt = m.createdAt;
            }
            if (!firstTaskTime) firstTaskTime = m.createdAt;
            hideSet.add(i);

            // Replay buffered TaskUpdates now that TaskCreates are known
            for (const pu of pendingUpdates) {
                applyTaskUpdate(pu.tid, pu.status);
            }
            pendingUpdates.length = 0;
        } else if (m.kind === 'tool-call' && m.tool?.name === 'TaskUpdate') {
            const input = m.tool?.input || {};
            const tid = (input.taskId || input.id || '') as string;
            const status = (input.status as string) || '';

            // Buffer if no TaskCreate has been seen yet
            if (firstTaskIdx < 0) {
                pendingUpdates.push({ tid, status });
                hideSet.add(i);
                continue;
            }

            applyTaskUpdate(tid, status);
            hideSet.add(i);
        } else if (m.kind === 'tool-call' && activeCount > 0) {
            // Absorb non‑task tool calls while tasks are running
            if (currentTaskIdx >= 0 && currentTaskIdx < taskItems.length) {
                taskItems[currentTaskIdx].collapsedCount =
                    (taskItems[currentTaskIdx].collapsedCount ?? 0) + 1;
            }
            hideSet.add(i);
        }
    }

    // ---- Absorb tool calls before first TaskCreate in the same turn ---------
    let preCount = 0;
    if (firstTaskIdx >= 0) {
        for (let i = firstTaskIdx - 1; i >= 0; i--) {
            const m = messages[i];
            if (
                m.kind === 'tool-call' ||
                m.kind === 'agent-text' ||
                m.kind === 'agent-event'
            ) {
                hideSet.add(i);
                if (m.kind === 'tool-call') preCount++;
            } else {
                break;
            }
        }
    }

    // ---- Pass 2: build result, inserting timeline card at firstTaskIdx -----
    const result: ClusteredMessage[] = [];
    for (let i = 0; i < messages.length; i++) {
        if (hideSet.has(i)) {
            if (i === firstTaskIdx && taskItems.length > 0) {
                const collapsedToolCount =
                    taskItems.reduce(
                        (sum, t) => sum + (t.collapsedCount ?? 0),
                        0,
                    ) + preCount;
                result.push({
                    id: 'task-timeline',
                    kind: 'task-cluster',
                    tasks: taskItems,
                    collapsedCount: collapsedToolCount,
                    createdAt: firstTaskCreatedAt,
                });
            }
            continue;
        }
        result.push(messages[i]);
    }

    // Edge case: all messages absorbed but timeline not yet in result
    if (
        firstTaskIdx >= 0 &&
        taskItems.length > 0 &&
        !result.some((r): r is TaskClusterMessage => r.kind === 'task-cluster')
    ) {
        result.splice(0, 0, {
            id: 'task-timeline',
            kind: 'task-cluster',
            tasks: taskItems,
            collapsedCount:
                taskItems.reduce(
                    (sum, t) => sum + (t.collapsedCount ?? 0),
                    0,
                ) + preCount,
            createdAt: firstTaskCreatedAt,
        });
    }

    return result;
}
